void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float k = U.p0.x;
    vec2 c = uv * 2.0 - 1.0;
    c *= 1.0 + k * dot(c, c);
    vec2 p = c * 0.5 + 0.5;
    if (p.x < 0.0 || p.x > 1.0 || p.y < 0.0 || p.y > 1.0) {
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }
    vec3 col = texture(iChannel0, p).rgb;
    vec3 glow = 0.25 * (texture(iChannel0, p + vec2(0.004, 0.0)).rgb + texture(iChannel0, p - vec2(0.004, 0.0)).rgb
                      + texture(iChannel0, p + vec2(0.0, 0.004)).rgb + texture(iChannel0, p - vec2(0.0, 0.004)).rgb);
    col += glow * 0.35;
    float scan = 0.75 + 0.25 * sin(p.y * iResolution.y * 1.5);
    float m = mod(fragCoord.x, 3.0);
    vec3 mask = m < 1.0 ? vec3(1.0, 0.7, 0.7) : (m < 2.0 ? vec3(0.7, 1.0, 0.7) : vec3(0.7, 0.7, 1.0));
    col *= scan * mask * 1.25;
    float vig = 16.0 * p.x * p.y * (1.0 - p.x) * (1.0 - p.y);
    col *= pow(vig, 0.25);
    col *= 0.97 + 0.03 * sin(iTime * 110.0);
    fragColor = vec4(col, 1.0);
}
